INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-11', 'lumina-atelier-sustainability-pledge', 'Practical Sustainability Targets for Bahrain Operations in 2026', 'مستهدفات الاستدامة العملية للعمليات في البحرين 2026', 'Key operational benchmarks, real metrics, and 2026 guidance from Lumina Atelier in Riffa.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من لومينا أتيليه في Riffa.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Curated beauty atelier combining bespoke facial rituals, hair artistry, and an online botanical skincare apothecary. Focusing on Botanical Hydration Facial (75 min), our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"أتيليه تجميل يجمع بين جلسات العناية بالبشرة المخصصة ومتجر إلكتروني لمنتجات العناية النباتية. من خلال خدمة جلسة ترطيب نباتي للوجه (75 دقيقة) نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Curated beauty atelier combining bespoke facial rituals, hair artistry, and an online botanical skincare apothecary.</p><p>Focusing on <strong>Botanical Hydration Facial (75 min)</strong>, our Riffa specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>أتيليه تجميل يجمع بين جلسات العناية بالبشرة المخصصة ومتجر إلكتروني لمنتجات العناية النباتية.</p><p>من خلال خدمة <strong>جلسة ترطيب نباتي للوجه (75 دقيقة)</strong>، يعمل فريقنا في Riffa على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-02.png', 'Practical Sustainability Targets for Bahrain Operations in 2026 | Lumina Atelier', 'مستهدفات الاستدامة العملية للعمليات في البحرين 2026 | لومينا أتيليه', 'Executive guide by Lumina Atelier covering Botanical Hydration Facial (75 min) benchmarks in Bahrain.', 'دليل تنفيذي من لومينا أتيليه حول معايير جلسة ترطيب نباتي للوجه (75 دقيقة) في البحرين.', 'Sustainability', '{"beauty","sustainability","Riffa","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '66 days', false, now() - interval '66 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-11', 'Can scope adjustments be added mid-project cleanly?', 'هل يمكن إضافة أو تعديل نطاق العمل أثناء تنفيذ المشروع؟', 'Any variation order generates a transparent delta quotation linked directly to the parent project and budget.', 'يتم إصدار ملحق تعديل واضح مرتبط مباشرة بميزانية المشروع الأساسية وموافقتكم.', 'changes', true, 11, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
